create extension if not exists "uuid-ossp";

create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,created_at timestamptz default now());
create table if not exists public.trades(id uuid primary key default uuid_generate_v4(),slug text unique not null,name text not null,description text,icon text,category text,level text default 'beginner',created_at timestamptz default now());
create table if not exists public.courses(id uuid primary key default uuid_generate_v4(),trade_id uuid references public.trades(id) on delete cascade,title text not null,level text default 'beginner',description text,published boolean default true,created_at timestamptz default now());
create table if not exists public.modules(id uuid primary key default uuid_generate_v4(),course_id uuid references public.courses(id) on delete cascade,title text not null,position int default 0);
create table if not exists public.lessons(id uuid primary key default uuid_generate_v4(),module_id uuid references public.modules(id) on delete cascade,title text not null,objective text,content text,safety_note text,position int default 0,published boolean default true);
create table if not exists public.lesson_assets(id uuid primary key default uuid_generate_v4(),lesson_id uuid references public.lessons(id) on delete cascade,asset_type text not null check(asset_type in ('image','diagram','video')),url text not null,alt_text text,position int default 0);
create table if not exists public.questions(id uuid primary key default uuid_generate_v4(),lesson_id uuid references public.lessons(id) on delete cascade,question text not null,options jsonb,answer text not null,explanation text);
create table if not exists public.progress(id uuid primary key default uuid_generate_v4(),user_id uuid references auth.users(id) on delete cascade,lesson_id uuid references public.lessons(id) on delete cascade,completed boolean default false,score int,updated_at timestamptz default now(),unique(user_id,lesson_id));
create table if not exists public.certificates(id uuid primary key default uuid_generate_v4(),user_id uuid references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete cascade,verification_id text unique not null,score int,issued_at timestamptz default now());

