alter table public.profiles enable row level security; alter table public.trades enable row level security; alter table public.courses enable row level security; alter table public.modules enable row level security; alter table public.lessons enable row level security; alter table public.lesson_assets enable row level security; alter table public.questions enable row level security; alter table public.progress enable row level security; alter table public.certificates enable row level security;

drop policy if exists "public read trades" on public.trades; create policy "public read trades" on public.trades for select using(true);
drop policy if exists "public read published courses" on public.courses; create policy "public read published courses" on public.courses for select using(published=true);
drop policy if exists "public read modules" on public.modules; create policy "public read modules" on public.modules for select using(true);
drop policy if exists "public read published lessons" on public.lessons; create policy "public read published lessons" on public.lessons for select using(published=true);
drop policy if exists "public read lesson assets" on public.lesson_assets; create policy "public read lesson assets" on public.lesson_assets for select using(true);
drop policy if exists "public read questions" on public.questions; create policy "public read questions" on public.questions for select using(true);
drop policy if exists "users read own progress" on public.progress; create policy "users read own progress" on public.progress for select using(auth.uid()=user_id);
drop policy if exists "users write own progress" on public.progress; create policy "users write own progress" on public.progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "users read own profile" on public.profiles; create policy "users read own profile" on public.profiles for select using(auth.uid()=id);
drop policy if exists "users insert own profile" on public.profiles; create policy "users insert own profile" on public.profiles for insert with check(auth.uid()=id);
drop policy if exists "users update own profile" on public.profiles; create policy "users update own profile" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "users read own certificates" on public.certificates; create policy "users read own certificates" on public.certificates for select using(auth.uid()=user_id);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id, coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

drop policy if exists "public read lesson assets bucket" on storage.objects; create policy "public read lesson assets bucket" on storage.objects for select using(bucket_id='lesson-assets');
